ALTER TABLE "billing"."billing_cash_scan" DROP CONSTRAINT "billing_cash_scan_state";--> statement-breakpoint
ALTER TABLE "billing"."billing_cash_scan" ADD CONSTRAINT "billing_cash_scan_state" CHECK ("billing"."billing_cash_scan"."state" IN ('pending','running','incomplete','complete','attention') AND ("billing"."billing_cash_scan"."state" <> 'complete' OR ("billing"."billing_cash_scan"."balance_done" AND "billing"."billing_cash_scan"."payment_intent_done" AND "billing"."billing_cash_scan"."charge_done" AND "billing"."billing_cash_scan"."refund_done" AND "billing"."billing_cash_scan"."journal_done" AND "billing"."billing_cash_scan"."fact_done" AND "billing"."billing_cash_scan"."completed_at" IS NOT NULL)));